import { NextResponse } from "next/server";
import { redis, relayConfigured, KEYS } from "../upstash";
import type { ProgressResponse } from "../../../lib/api-types";

// Per-question progress. The /ask page polls this while its answer request is in
// flight, so a visitor can see whether their question is waiting behind others or
// actually being written — rather than staring at a spinner for 20 seconds.

export const revalidate = 0;

export async function GET(req: Request) {
  const url = new URL(req.url);
  const id = url.searchParams.get("id") ?? "";
  // ids are generated by the browser, so treat them as untrusted input: only ever
  // interpolate something that looks like a uuid into a key name.
  if (!/^[0-9a-f-]{8,64}$/i.test(id)) {
    return NextResponse.json({ state: "unknown" } satisfies ProgressResponse);
  }
  if (!relayConfigured()) {
    return NextResponse.json({ state: "offline" } satisfies ProgressResponse);
  }

  try {
    const answer = await redis(["GET", KEYS.answer(id)], 4000);
    if (answer) {
      // consume the answer so it doesn't linger in the relay
      redis(["DEL", KEYS.answer(id)], 3000).catch(() => {});
      return NextResponse.json({ state: "done", answer: String(answer), ahead: 0 } satisfies ProgressResponse);
    }
    const raw = await redis(["GET", KEYS.progress(id)], 4000);
    if (!raw) {
      // No state yet: the node has not picked it up, so it is still in line —
      // and only now is the queue depth worth a second command.
      // An extended job waits behind every normal one as well as earlier extended ones.
      const lists = url.searchParams.get("x") === "1" ? [KEYS.jobs, KEYS.extendedJobs] : [KEYS.jobs];
      const depths = await Promise.all(lists.map((k) => redis(["LLEN", k], 4000)));
      const ahead = depths.reduce<number>((n, d) => n + (Number(d ?? 0) || 0), 0);
      return NextResponse.json({ state: "queued", ahead } satisfies ProgressResponse);
    }
    const p = JSON.parse(String(raw)) as { state?: string; via?: string; ms?: number };
    return NextResponse.json({
      state: p.state ?? "queued",
      via: p.via ?? null,
      ms: p.ms ?? null,
      ahead: 0,
    } satisfies ProgressResponse);
  } catch {
    return NextResponse.json({ state: "unknown" } satisfies ProgressResponse);
  }
}
